	{"file-paths", "modified: cmd/entire/cli/strategy/manual_commit_condensation.go and redact/redact.go", ""},
	{"git-sha", "commit dc7f04573d30d90d92b7370b59ee99ebbf42d131 (HEAD -> main)", ""},
