```go
var (
	initRedactionOnce sync.Once
	redactionScannerErr error
)

// EnsureRedactionConfigured loads redaction settings and configures the
// redact package: scanner engines, PII detection (opt-in), inline
// custom_redactions, and rule packs.
//
// Must be called at each process entry point before checkpoint writes.
// Returns an error ONLY for scanner-specific failures (invalid scanner
// config, goredact engine construction) — these must fail the operation,
// since proceeding would run a scanner set the team's committed settings
// did not choose. All other settings problems keep the historical
// warn-and-default behavior.
func EnsureRedactionConfigured() error {
	initRedactionOnce.Do(func() {
		ctx := context.Background()
		s, err := settings.Load(ctx)
		if err != nil {
			if errors.Is(err, settings.ErrScannerConfig) {
				redactionScannerErr = err
				return
			}
			logCtx := logging.WithComponent(ctx, "redaction")
			logging.Warn(logCtx, "failed to load settings for redaction", slog.String("error", err.Error()))
			return
		}

		if err := redact.ConfigureScanners(redact.ScannersConfig{
			Betterleaks: s.BetterleaksEnabled(),
			Goredact:    s.GoredactEnabled(),
		}); err != nil {
			redactionScannerErr = fmt.Errorf("%w: %v", settings.ErrScannerConfig, err)
			return
		}
		maybeWarnNarrowedScanners(ctx, s)

		// ... existing PII / custom rules / packs body unchanged ...
	})
	return redactionScannerErr
}

// resetRedactionConfiguredForTesting reinitializes the Once so tests can
// exercise different settings fixtures in one process.
func resetRedactionConfiguredForTesting() {
	initRedactionOnce = sync.Once{}
	redactionScannerErr = nil
}
```

`maybeWarnNarrowedScanners` (same file):

```go
// maybeWarnNarrowedScanners prints a one-line stderr note when betterleaks
// is disabled, once per effective scanner configuration. The marker lives
// on a gitignored path (same ignore treatment as settings.local.json) so
// it can never land committable. Best-effort: marker IO failures degrade
// to warning every run, never to silence.
func maybeWarnNarrowedScanners(ctx context.Context, s *settings.EntireSettings) {
	if s.BetterleaksEnabled() {
		return
	}
	fingerprint := fmt.Sprintf("betterleaks=%t goredact=%t\n", s.BetterleaksEnabled(), s.GoredactEnabled())
	markerRel := filepath.Join(paths.EntireDir, "logs", "scanner-notice")
	markerAbs, err := paths.AbsPath(ctx, markerRel)
	if err != nil {
		markerAbs = markerRel
	}
	if prev, rerr := os.ReadFile(markerAbs); rerr == nil && string(prev) == fingerprint {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] betterleaks scanning is disabled in .entire/settings.json; checkpoint redaction relies on the remaining layers"+goredactSuffix(s)+".")
	_ = os.MkdirAll(filepath.Dir(markerAbs), 0o755)
	_ = os.WriteFile(markerAbs, []byte(fingerprint), 0o644)
}

func goredactSuffix(s *settings.EntireSettings) string {
	if s.GoredactEnabled() {
		return " plus goredact"
	}
	return ""
}
```

